package io.github.finalparadox.entity;
import io.github.finalparadox.ability.GlaivorusAbilityState;import io.github.finalparadox.registry.ModEntities;import net.minecraft.core.particles.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.ClientGamePacketListener;import net.minecraft.server.level.*;import net.minecraft.sounds.*;import net.minecraft.world.effect.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.phys.*;import net.minecraftforge.network.NetworkHooks;import org.joml.Vector3f;import java.util.*;
public final class ChestLaserEntity extends Entity{private UUID ownerId;private final Map<UUID,Integer>hitCd=new HashMap<>();public ChestLaserEntity(EntityType<ChestLaserEntity>t,Level l){super(t,l);noPhysics=true;noCulling=true;}public static void spawn(ServerPlayer owner){for(ChestLaserEntity old:owner.serverLevel().getEntitiesOfClass(ChestLaserEntity.class,owner.getBoundingBox().inflate(128),e->owner.getUUID().equals(e.ownerId)))old.discard();ChestLaserEntity e=new ChestLaserEntity(ModEntities.CHEST_LASER.get(),owner.serverLevel());e.ownerId=owner.getUUID();e.setPos(owner.position());owner.serverLevel().addFreshEntity(e);owner.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,300,0));owner.serverLevel().playSound(null,owner.blockPosition(),SoundEvents.ILLUSIONER_PREPARE_BLINDNESS,SoundSource.PLAYERS,2,1);}
 @Override protected void defineSynchedData(){}@Override public void tick(){super.tick();if(level().isClientSide)return;if(!(level() instanceof ServerLevel s)){discard();return;}ServerPlayer o=ownerId==null?null:s.getServer().getPlayerList().getPlayer(ownerId);if(o==null||tickCount>70){discard();return;}setPos(o.getX(),o.getY()+.1,o.getZ());Vec3 start=o.position().add(0,1.2,0),dir=o.getLookAngle().normalize();hitCd.replaceAll((id,v)->v-1);hitCd.entrySet().removeIf(e->e.getValue()<=0);for(int i=1;i<=40;i++){Vec3 p=start.add(dir.scale(i*.43));s.sendParticles(new DustParticleOptions(new Vector3f(1,0,0),1.5F),p.x,p.y,p.z,1,.03,.03,.03,0);if((i+tickCount)%8==0)s.sendParticles(ParticleTypes.FIREWORK,p.x,p.y,p.z,1,0,0,0,.1);}AABB box=new AABB(start,start.add(dir.scale(17.2))).inflate(1.2);for(LivingEntity target:s.getEntitiesOfClass(LivingEntity.class,box,e->GlaivorusAbilityState.isHostileTarget(o,e)&&!hitCd.containsKey(e.getUUID()))){Vec3 nearest=nearestOnSegment(target.position().add(0,target.getBbHeight()*.5,0),start,start.add(dir.scale(17.2)));if(target.getBoundingBox().inflate(1).contains(nearest)&&target.hurt(o.damageSources().playerAttack(o),11)){hitCd.put(target.getUUID(),10);target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,20,1),o);target.setSecondsOnFire(5);s.sendParticles(ParticleTypes.LAVA,target.getX(),target.getY()+1,target.getZ(),2,0,0,0,1);}}}
 private static Vec3 nearestOnSegment(Vec3 p,Vec3 a,Vec3 b){Vec3 ab=b.subtract(a);double t=Math.max(0,Math.min(1,p.subtract(a).dot(ab)/ab.lengthSqr()));return a.add(ab.scale(t));}
 @Override protected void readAdditionalSaveData(CompoundTag t){if(t.hasUUID("Owner"))ownerId=t.getUUID("Owner");}@Override protected void addAdditionalSaveData(CompoundTag t){if(ownerId!=null)t.putUUID("Owner",ownerId);}@Override public Packet<ClientGamePacketListener>getAddEntityPacket(){return NetworkHooks.getEntitySpawningPacket(this);}}
